<?php

declare(strict_types=1);

namespace Ritmo\Tests\Support;

use ReflectionClass;
use RuntimeException;

/**
 * Keeps the signature references at the end of docs/CONTRACTS.md and docs/ENGINE.md identical to
 * the code.
 *
 * A reference is generated by reflection from every type under the folders of its document, so the
 * signatures in the document are exact by construction. `php bin/sync-generated.php` rewrites it and
 * a test fails when it is stale.
 */
final class ContractsDoc
{
    public const BEGIN = '<!-- BEGIN GENERATED SIGNATURES (php bin/sync-generated.php) -->';

    public const END = '<!-- END GENERATED SIGNATURES -->';

    /** The shared contracts: what every module builds on. */
    public const CONTRACTS = 'CONTRACTS.md';

    /** The rule engine: what the application and the panel call. */
    public const ENGINE = 'ENGINE.md';

    /** Document => folders under src/ whose public surface it lists, in document order. */
    private const FOLDERS = [
        self::CONTRACTS => ['Domain/Support', 'Domain/Model', 'Domain/Config', 'Contracts'],
        self::ENGINE => ['Domain/Calendar', 'Domain/Market', 'Domain/Pricing', 'Domain/Plan', 'Domain/Report'],
    ];

    public static function path(string $document = self::CONTRACTS): string
    {
        return Fixtures::pluginRoot() . '/docs/' . $document;
    }

    /**
     * The reference section as Markdown, markers included.
     */
    public static function render(string $document = self::CONTRACTS): string
    {
        $src = Fixtures::pluginRoot() . '/src/';
        $out = [self::BEGIN, ''];
        foreach (self::FOLDERS[$document] as $folder) {
            foreach (SourceScan::phpFiles($src . $folder) as $file) {
                $declared = SourceScan::declarations((string) file_get_contents($file));
                /** @var class-string $class */
                $class = $declared['namespace'] . '\\' . $declared['types'][0];
                $out[] = sprintf('#### `%s` (%s)', $class, self::kind(new ReflectionClass($class)));
                $out[] = '';
                $out[] = '```php';
                array_push($out, ...(SignaturePrinter::lines($class) ?: ['// no public members']));
                $out[] = '```';
                $out[] = '';
            }
        }
        $out[] = self::END;

        return implode("\n", $out);
    }

    /**
     * The reference section currently in the document, markers included.
     *
     * @throws RuntimeException when the document or its markers are missing
     */
    public static function current(string $document = self::CONTRACTS): string
    {
        [$before, $section] = self::split($document);

        return $section;
    }

    /**
     * Rewrites the reference section of the document. Returns true when the file changed.
     */
    public static function sync(string $document = self::CONTRACTS): bool
    {
        [$before, $section, $after] = self::split($document);
        $fresh = self::render($document);
        if ($fresh === $section) {
            return false;
        }
        file_put_contents(self::path($document), $before . $fresh . $after);

        return true;
    }

    /**
     * @return array{string, string, string} text before the section, the section, text after it
     */
    private static function split(string $document): array
    {
        $text = is_file(self::path($document)) ? (string) file_get_contents(self::path($document)) : '';
        $begin = strpos($text, self::BEGIN);
        $end = strpos($text, self::END);
        if ($begin === false || $end === false || $end < $begin) {
            throw new RuntimeException(sprintf('docs/%s is missing or has lost its generated-signatures markers.', $document));
        }
        $end += strlen(self::END);

        return [substr($text, 0, $begin), substr($text, $begin, $end - $begin), substr($text, $end)];
    }

    /**
     * @param ReflectionClass<object> $class
     */
    private static function kind(ReflectionClass $class): string
    {
        $kind = match (true) {
            $class->isInterface() => 'interface',
            $class->isTrait() => 'trait',
            $class->isEnum() => 'enum',
            $class->isFinal() => 'final class',
            default => 'class',
        };
        $parent = $class->getParentClass();

        return $parent === false ? $kind : $kind . ' extends ' . $parent->getShortName();
    }
}
